CREATE OR REPLACE FUNCTION public.dispatch_crm_emails(callback_url text, publishable_key text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE local_now timestamp := now() AT TIME ZONE 'Europe/Helsinki'; run_kind text; run_period text; new_id uuid; BEGIN IF extract(hour FROM local_now) <> 9 THEN RETURN; END IF; FOREACH run_kind IN ARRAY CASE WHEN extract(isodow FROM local_now)=1 THEN ARRAY['daily','weekly'] ELSE ARRAY['daily'] END LOOP run_period := CASE WHEN run_kind='daily' THEN local_now::date::text ELSE (date_trunc('week',local_now)::date-7)::text END; INSERT INTO public.crm_email_runs(kind,period_key) VALUES(run_kind,run_period) ON CONFLICT(kind,period_key) DO NOTHING RETURNING id INTO new_id; IF new_id IS NOT NULL THEN PERFORM net.http_post(url:=callback_url,headers:=jsonb_build_object('Content-Type','application/json','apikey',publishable_key),body:=jsonb_build_object('run_id',new_id),timeout_milliseconds:=120000); END IF; new_id:=NULL; END LOOP; END; $$;
REVOKE ALL ON FUNCTION public.dispatch_crm_emails(text,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.dispatch_crm_emails(text,text) TO service_role;